def dup_pairs(W,thr=0.8):
    Wn=torch.nn.functional.normalize(W,dim=1); C=Wn@Wn.T; C.fill_diagonal_(0)
    idx=torch.nonzero(C.abs()>thr)
    return [(int(i),int(j),round(float(C[i,j]),3)) for i,j in idx if i<j]
